$ cat Live.java
public class Live {
    public static void main(String[] a) throws Exception {
        int liveEvery = Integer.parseInt(a[0]);   // 작을수록 오래 사는 것이 많다
        List<byte[]> live = new ArrayList<>();
        Deque<byte[]> churn = new ArrayDeque<>();
        for (int i = 0; i < 60000; i++) {
            churn.add(new byte[8 * 1024]);
            if (churn.size() > 100) churn.poll();       // 금방 버린다
            if (i % liveEvery == 0) live.add(new byte[8 * 1024]);
        }
    }
}

